fn is_nested(s: Vec<i8>) -> bool {
    // We want to find indices i < j < k < l such that
    // s[i] = 0, s[j] = 0, s[k] = 1, s[l] = 1.
    //
    // First, locate the second occurrence of 0 in the vector.
    // If there are fewer than two 0's, we cannot satisfy the pattern.
    let mut zero_count = 0;
    let mut second_zero_idx = 0;
    for (i, &v) in s.iter().enumerate() {
        if v == 0 {
            zero_count += 1;
            if zero_count == 2 {
                second_zero_idx = i;
                break;
            }
        }
    }
    if zero_count < 2 {
        return false;
    }

    // From the position after the second 0, look for two 1's.
    // If we find them, we have indices i<j<k<l with the required values.
    let mut one_count = 0;
    for &v in &s[second_zero_idx + 1..] {
        if v == 1 {
            one_count += 1;
            if one_count == 2 {
                return true;
            }
        }
    }

    // If we never saw two 1's after the second 0, no valid subsequence exists.
    false
}

